package com.opensocket.aievent.database.persistence.a2a.repository;
import java.time.OffsetDateTime; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AResultQuarantineRepository implements A2AResultQuarantineRepository { private final A2AResultQuarantineDao dao; private final A2APersistenceConverter c; public MybatisA2AResultQuarantineRepository(A2AResultQuarantineDao d,A2APersistenceConverter c){dao=d;this.c=c;} public A2AResultQuarantine save(A2AResultQuarantine v){dao.upsert(c.toPo(v));return findByAttempt(v.getTenantId(),v.getAttemptId()).orElse(v);} public Optional<A2AResultQuarantine> findById(String t,String id){return Optional.ofNullable(dao.findById(t,id)).map(c::toDomain);} public Optional<A2AResultQuarantine> findByAttempt(String t,String id){return Optional.ofNullable(dao.findByAttempt(t,id)).map(c::toDomain);} public List<A2AResultQuarantine> findOpen(String t,int n){return dao.findOpen(t,Math.max(1,Math.min(n,1000))).stream().map(c::toDomain).toList();} public List<A2AResultQuarantine> findByRequest(String t,String id,int n){return dao.findByRequest(t,id,Math.max(1,Math.min(n,1000))).stream().map(c::toDomain).toList();} public boolean resolveExpectedStatus(String t,String id,String e,String target,String by,String reason,OffsetDateTime at){return dao.resolveExpectedStatus(t,id,e,target,by,reason,at)==1;} public String mode(){return "MYBATIS";} }
